import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int a = sc.nextInt();
        int b = sc.nextInt();

        // 割る数が0かどうかを先に確かめる
        if (b == 0) {
            System.out.println("0では割れません");
        } else {
            System.out.println(a / b);
        }

        // 小数の割り算は例外にならない
        System.out.println((double) a / b);
    }
}

